('403c2680-d4d6-4121-9c26-3c14db6153d6','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"2.DESCARTAR","car_obs_MEDIAPUNTA":"DAMIAN ES UN GRAN JUGADOR, ESTA EN EL CIERRE DE SU CARRERA. LLEGO EN ESTE MERCADO A BARCELONA.","car_obs_mediapunta":"DAMIAN ES UN GRAN JUGADOR, ESTA EN EL CIERRE DE SU CARRERA. LLEGO EN ESTE MERCADO A BARCELONA."}'),
