('4c2695fb-aa54-4021-ae1b-a555a30a5c02','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_MEDIOCENTRO":"Pivote de bastante experiencia en el fútbol ecuatoriano, con pasado en selección y ex mundialista con Ecuador. Características de bastante recuperación de balón, decidido al roce y duelos individuales, propenso a la tarjeta amarilla pero no suele sobrepasarse para ser expulsado, atento a captar segundas pelotas. Técnicamente no fué un jugador llamativo, pero tácticamente en su función bastante cumplidor y entrega total por los equipos dónde ha estado, actualmente libre sin club, perfil a seguirlo de cerca.","car_obs_mediocentro":"Pivote de bastante experiencia en el fútbol ecuatoriano, con pasado en selección y ex mundialista con Ecuador. Características de bastante recuperación de balón, decidido al roce y duelos individuales, propenso a la tarjeta amarilla pero no suele sobrepasarse para ser expulsado, atento a captar segundas pelotas. Técnicamente no fué un jugador llamativo, pero tácticamente en su función bastante cumplidor y entrega total por los equipos dónde ha estado, actualmente libre sin club, perfil a seguirlo de cerca."}'),
('4ccec934-077e-4d60-b41d-e613a6c441c8','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","att_MEDIAPUNTA_capacidad_creativa":"4","att_MEDIAPUNTA_referencia_posicional":"4","att_MEDIAPUNTA_capacidad_de_crear_opcion_de_gol_finalizacion":"3","att_MEDIAPUNTA_duelos_1vs1":"3","att_MEDIAPUNTA_capacidad_de_recuperar_y_dar_continuidad_al_juego":"3","att_MEDIAPUNTA_dominio_del_ritmo_del_juego":"3","att_MEDIAPUNTA_participacion_activa_en_el_juego":"3","tac_trans_da":"3","tac_trans_ad":"2","tec_obs":"Se mueve bien entre líneas y también realiza apoyos para participar en el juego. Puede descargar de primera como girar y descargar hacia el otro costado. Ofrece claridad en último tercio","att_mediapunta_capacidad_creativa":"4","att_mediapunta_referencia_posicional":"4","att_mediapunta_capacidad_de_crear_opcion_de_gol_finalizacion":"3","att_mediapunta_duelos_1vs1":"3","att_mediapunta_capacidad_de_recuperar_y_dar_continuidad_al_juego":"3","att_mediapunta_dominio_del_ritmo_del_juego":"3","att_mediapunta_participacion_activa_en_el_juego":"3"}'),
